float dtl(vec2 P, vec2 p1, vec2 p2) {
    P -= p1;
    p2 -= p1;
    return abs( p2.y*P.x - p2.x*P.y ) / length(p2);
}

mat2 rot(float a) {
    float c = cos(a);
    float s = sin(a);
    return mat2(c,s,s,-c);
}

vec3 cmap(float v, vec3 s) {
    return clamp(vec3(v,v,v)-s,0.0,1.0);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = (fragCoord * 2.0 - iResolution.xy) / iResolution.y;

    float a = atan(uv.y, uv.x);
    float l = length(uv);
    uv = rot(a*5.0+l*4.0)*uv;

    const float n = 21.0;
    vec3 c=vec3(0.0);
    for(float j=0.0;j<n;++j) {
        float q = j/n-0.5;
        vec2 c0 = vec2(q,cos(iTime));
        vec2 c1 = vec2(sin(iTime/2.0),q);
        float d= dtl(uv, c0,c1);
        d = pow(d,1.5)*1e3;
        d = 4.0/(d+1.0);
        c[int(j/7.0)]+=d;
    }
    vec3 col = cmap(c[0],vec3(0.0,1.0,2.0));
    col += cmap(c[1],vec3(2.0,0.0,1.0));
    col += cmap(c[2],vec3(1.0,2.0,0.0));
    col = clamp(col,0.0,1.0);

    fragColor = vec4(col,1.0);
}
